const cubicPoint = (p0: Point, p1: Point, p2: Point, p3: Point, t: number): Point => { const u = 1 - t; return { x: u ** 3 * p0.x + 3 * u ** 2 * t * p1.x + 3 * u * t ** 2 * p2.x + t ** 3 * p3.x, y: u ** 3 * p0.y + 3 * u ** 2 * t * p1.y + 3 * u * t ** 2 * p2.y + t ** 3 * p3.y }; };
const flattenBezier = (p0: Point, p1: Point, p2: Point, p3: Point, tolerance = 0.65, depth = 0): Point[] => {
  const chord = Math.hypot(p3.x - p0.x, p3.y - p0.y); const control = Math.hypot(p1.x - p0.x, p1.y - p0.y) + Math.hypot(p2.x - p1.x, p2.y - p1.y) + Math.hypot(p3.x - p2.x, p3.y - p2.y);
  if (depth > 9 || control - chord < tolerance) return [p0, p3];
  const p01 = { x: (p0.x + p1.x) / 2, y: (p0.y + p1.y) / 2 }; const p12 = { x: (p1.x + p2.x) / 2, y: (p1.y + p2.y) / 2 }; const p23 = { x: (p2.x + p3.x) / 2, y: (p2.y + p3.y) / 2 }; const p012 = { x: (p01.x + p12.x) / 2, y: (p01.y + p12.y) / 2 }; const p123 = { x: (p12.x + p23.x) / 2, y: (p12.y + p23.y) / 2 }; const mid = { x: (p012.x + p123.x) / 2, y: (p012.y + p123.y) / 2 };
  return [...flattenBezier(p0, p01, p012, mid, tolerance, depth + 1).slice(0, -1), ...flattenBezier(mid, p123, p23, p3, tolerance, depth + 1)];
};
const elementRing = (element: DesignElement): Ring | null => {
  if (element.type === "rect") return [[element.x, element.y], [element.x + element.w, element.y], [element.x + element.w, element.y + element.h], [element.x, element.y + element.h], [element.x, element.y]];
  if (element.type === "ellipse") return Array.from({ length: 65 }, (_, index) => { const angle = (index / 64) * Math.PI * 2; return [element.x + element.w / 2 + Math.cos(angle) * Math.abs(element.w) / 2, element.y + element.h / 2 + Math.sin(angle) * Math.abs(element.h) / 2] as [number, number]; });
  if (element.type === "path" && element.nodes?.length) {
    const ring: Point[] = [];
    element.nodes.forEach((node, index) => { const next = element.nodes?.[(index + 1) % element.nodes.length]; if (!next) return; ring.push(...flattenBezier({ x: node.x, y: node.y }, node.outHandle, next.inHandle, { x: next.x, y: next.y }).slice(0, -1)); });
    if (element.closed) ring.push(ring[0]);
    return ring.map((point) => [point.x, point.y] as [number, number]);
  }
  return null;
};
const ringsToPath = (multiPolygon: number[][][][]) => multiPolygon.flatMap((polygon) => polygon).map((ring) => `${ring.map(([x, y], index) => `${index ? "L" : "M"} ${x} ${y}`).join(" ")} Z`).join(" ");
const compoundCurvePath = (segments: BezierNode[][]) => segments.map((nodes) => buildPathD(nodes, true)).join(" ");
const boundsOverlap = (a: DesignElement, b: DesignElement) => { const left = Math.max(a.x, b.x); const top = Math.max(a.y, b.y); const right = Math.min(a.x + a.w, b.x + b.w); const bottom = Math.min(a.y + a.h, b.y + b.h); return right > left && bottom > top; };

const snapScalar = (value: number, guides: Guide[], orientation: Orientation, snap: boolean) => {
  if (!snap) return value;
  const gridValue = Math.round(value / 24) * 24;
  const guideValue = guides.filter((guide) => guide.orientation === orientation).reduce((closest, guide) => Math.abs(guide.position - value) < Math.abs(closest - value) ? guide.position : closest, value);
  return Math.abs(guideValue - value) < 10 ? guideValue : gridValue;
};
const snapPoint = (point: Point, guides: Guide[], snap: boolean): Point => ({ x: snapScalar(point.x, guides, "vertical", snap), y: snapScalar(point.y, guides, "horizontal", snap) });
const parseNumber = (value: string | null, fallback: number) => { const number = Number(value); return Number.isFinite(number) ? number : fallback; };
const escapeXml = (value: string) => value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

