function validatePresetPayload(input: unknown): { ok: true; value: PresetPayload } | { ok: false; reason: string } {
  if (!input || typeof input !== "object") return { ok: false, reason: "Preset must be a JSON object." };
  const payload = input as Partial<PresetPayload>;
  if (payload.format !== "vectorforge-preset") return { ok: false, reason: "Unsupported preset format." };
  if (payload.version !== 1) return { ok: false, reason: "This preset version is not supported." };
  if (!Array.isArray(payload.pages) || payload.pages.length === 0) return { ok: false, reason: "Preset must contain at least one artboard." };
  if (!payload.pages.every((page) => page && typeof page.id === "string" && typeof page.name === "string" && Array.isArray(page.elements) && Array.isArray(page.guides))) return { ok: false, reason: "One or more artboards are malformed." };
  return { ok: true, value: { format: "vectorforge-preset", version: 1, pages: payload.pages as Page[], zoom: clamp(Number(payload.zoom) || 100, 50, 220), showGrid: Boolean(payload.showGrid), snap: payload.snap !== false, exportedAt: typeof payload.exportedAt === "string" ? payload.exportedAt : new Date().toISOString() } };
}

function validateVersionArchive(input: unknown): { ok: true; value: VersionArchive } | { ok: false; reason: string } {
  if (!input || typeof input !== "object") return { ok: false, reason: "Archive must be a JSON object." }; const archive = input as Partial<VersionArchive>;
  if (archive.format !== "vectorforge-version-archive" || archive.version !== 1 || !Array.isArray(archive.versions)) return { ok: false, reason: "Unsupported or malformed VectorForge archive." };
  if (!archive.versions.every((item) => item && typeof item.id === "string" && typeof item.name === "string" && typeof item.createdAt === "string" && Array.isArray(item.pages))) return { ok: false, reason: "Archive contains an invalid version record." };
  return { ok: true, value: { format: "vectorforge-version-archive", version: 1, exportedAt: typeof archive.exportedAt === "string" ? archive.exportedAt : new Date().toISOString(), versions: archive.versions as VersionRecord[] } };
}

function versionDiff(version: VersionRecord, currentPages: Page[]) {
  const currentObjects = currentPages.reduce((sum, page) => sum + page.elements.length, 0); const versionObjects = version.pages.reduce((sum, page) => sum + page.elements.length, 0);
  return `${version.pages.length - currentPages.length >= 0 ? "+" : ""}${version.pages.length - currentPages.length} pages · ${versionObjects - currentObjects >= 0 ? "+" : ""}${versionObjects - currentObjects} objects`;
}

function loadVersions(): VersionRecord[] {
  if (typeof window === "undefined") return [];
  try { const stored = window.localStorage.getItem(VERSIONS_KEY); const parsed = stored ? JSON.parse(stored) as VersionRecord[] : []; return Array.isArray(parsed) ? parsed : []; } catch { return []; }
}

function loadDocuments(): SavedDocument[] {
  if (typeof window === "undefined") return [];
  try { const stored = window.localStorage.getItem(DOCUMENTS_KEY); const parsed = stored ? JSON.parse(stored) as SavedDocument[] : []; return Array.isArray(parsed) ? parsed : []; } catch { return []; }
}

function loadPages(): Page[] {
  if (typeof window === "undefined") return initialPages;
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (!stored) return initialPages;
    const parsed = JSON.parse(stored) as Page[];
    return Array.isArray(parsed) && parsed.length > 0 && parsed[0]?.elements ? parsed : initialPages;
  } catch { return initialPages; }
}

function toolToElementType(tool: Tool): ElementType | null {
  if (tool === "rect") return "rect";
  if (tool === "ellipse") return "ellipse";
  if (tool === "line") return "line";
  return null;
}

